3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import jakarta.persistence.PostPersist;
7	
8	/**
9	 * Emits an audit trail entry via the dedicated {@code AUDIT} logger whenever a new
10	 * owner is persisted, carrying the owner id, customer code and registration date.
11	 */
12	public class OwnerAuditListener {
13	
14	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
15	
16	    @PostPersist
17	    void onCreate(Owner owner) {
18	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
19	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
20	    }
21	}
