3	import java.time.LocalDate;
4	import java.util.Collection;
5	
6	import org.springframework.samples.petclinic.model.BusinessDays;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Enforces the per-day create limit: at most {@link #LIMIT} owners may be
11	 * registered on any single day (compared by {@code registrationDate}).
12	 */
13	final class DailyRegistrationLimit {
14	
15	    static final int LIMIT = 100;
16	
17	    private DailyRegistrationLimit() {
18	    }
19	
20	    /**
21	     * Returns {@code true} when {@link #LIMIT} or more of the {@code existing} owners were
22	     * already registered today, so no further owner may be created today.
23	     */
24	    static boolean isReached(Collection<Owner> existing) {
25	        LocalDate today = BusinessDays.roll(LocalDate.now());
26	        long createdToday = existing.stream()
27	            .filter(other -> today.equals(other.getRegistrationDate()))
28	            .count();
29	        return createdToday >= LIMIT;
30	    }
31	}
