1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.Collection;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Detects owners that share a household, i.e. have the same last name and address
11	 * (compared case-insensitively with collapsed whitespace).
12	 */
13	final class HouseholdDuplicates {
14	
15	    private HouseholdDuplicates() {
16	    }
17	
18	    /**
19	     * Returns {@code true} when an existing owner shares {@code candidate}'s household and the
20	     * request did not opt in via {@code sharesHousehold}.
21	     */
22	    static boolean isRejectedDuplicate(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
23	        if (Boolean.TRUE.equals(sharesHousehold)) {
24	            return false;
25	        }
26	        String key = key(candidate);
27	        return existing.stream().anyMatch(other -> key(other).equals(key));
28	    }
29	
30	    /**
31	     * When {@code candidate} opted in via {@code sharesHousehold}, stamps it with its household's
32	     * stable shared id (derived from last name and address) so every member of the same household
33	     * carries the same id, whether it is the first member or joins existing ones.
34	     */
35	    static void assignHousehold(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
36	        if (!Boolean.TRUE.equals(sharesHousehold)) {
37	            return;
38	        }
39	        String key = key(candidate);
40	        candidate.setHouseholdId(householdId(key));
41	        long members = 1 + existing.stream().filter(other -> key(other).equals(key)).count();
42	        candidate.setHouseholdSize((int) members);
43	    }
44	
45	    private static String householdId(String key) {
46	        try {
47	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
48	            StringBuilder sb = new StringBuilder();
49	            for (int i = 0; i < 8; i++) {
50	                sb.append(String.format("%02x", digest[i]));
51	            }
52	            return sb.toString();
53	        }
54	        catch (Exception e) {
55	            throw new IllegalStateException(e);
56	        }
57	    }
58	
59	    private static String key(Owner owner) {
60	        return norm(owner.getLastName()) + "\n" + norm(owner.getAddress());
61	    }
62	
63	    private static String norm(String value) {
64	        return value == null ? "" : value.replaceAll("\\s+", " ").trim().toLowerCase();
65	    }
66	}
