5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Enforces the per-city capacity limit: a city may hold at most {@link #LIMIT} owners.
9	 */
10	final class CityCapacity {
11	
12	    static final int LIMIT = 50;
13	
14	    private CityCapacity() {
15	    }
16	
17	    /**
18	     * Returns {@code true} when {@code candidate}'s city already holds {@link #LIMIT} or more of
19	     * the {@code existing} owners (city compared case-insensitively), so it cannot take another.
20	     */
21	    static boolean isAtCapacity(Owner candidate, Collection<Owner> existing) {
22	        long inCity = existing.stream()
23	            .filter(other -> candidate.getCity().equalsIgnoreCase(other.getCity()))
24	            .count();
25	        return inCity >= LIMIT;
26	    }
27	}
