3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Business-day helper: a registration date must fall on a business day, so a
8	 * Saturday or Sunday is rolled forward to the next Monday.
9	 */
10	public final class BusinessDays {
11	
12	    private BusinessDays() {
13	    }
14	
15	    /**
16	     * Returns {@code date} unchanged when it is a weekday, or the following Monday
17	     * when it falls on a weekend.
18	     */
19	    public static LocalDate roll(LocalDate date) {
20	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
21	            date = date.plusDays(1);
22	        }
23	        return date;
24	    }
25	}
