19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.validation.BindingResult;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.WebDataBinder;
38	import org.springframework.web.bind.annotation.ControllerAdvice;
39	import org.springframework.web.bind.annotation.ExceptionHandler;
40	import org.springframework.web.bind.annotation.InitBinder;
41	import org.springframework.web.bind.annotation.ResponseBody;
42	
43	/**
44	 * Global Exception handler for REST controllers.
45	 * <p>
46	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
47	 *
48	 * @author Vitaliy Fedoriv
49	 * @author Alexander Dudkin
50	 */
51	@ControllerAdvice
52	public class ExceptionControllerAdvice {
53	
54	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
55	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
56	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
57	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
58	
59	    private final OwnerFieldsValidator ownerFieldsValidator = new OwnerFieldsValidator();
60	
61	    /**
62	     * Registers the {@link OwnerFieldsValidator} for {@link OwnerFieldsDto} request bodies so a
63	     * missing or blank required field is reported alongside the schema's own constraints.
64	     *
65	     * @param binder the data binder for the request body being bound
66	     */
67	    @InitBinder
68	    public void registerOwnerFieldsValidator(WebDataBinder binder) {
69	        if (binder.getTarget() instanceof OwnerFieldsDto) {
70	            binder.addValidators(ownerFieldsValidator);
71	        }
72	    }
73	
74	    /**
75	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
76	     * class.
77	     *
78	     * @param e     Object referring to the thrown exception.
79	     * @param status HTTP response status.
80	     * @param url URL request.
81	     */
82	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
83	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
84	        problemDetail.setType(URI.create(url.toString()));
85	        problemDetail.setTitle(e.getClass().getSimpleName());
86	        problemDetail.setDetail(detail);
87	        problemDetail.setProperty("timestamp", Instant.now());
88	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
89	        return problemDetail;
90	    }
91	
92	    /**
93	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
94	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
95	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
96	     * would catch it and report an authorization failure as a 500.
97	     *
98	     * @param e The {@link AccessDeniedException} to propagate
99	     * @throws AccessDeniedException always
100	     */
101	    @ExceptionHandler(AccessDeniedException.class)
102	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
103	        throw e;
104	    }
105	
106	    /**
107	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
108	     *
109	     * @param e The {@link Exception} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
112	     */
113	    @ExceptionHandler(Exception.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
116	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
117	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
118	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
119	        return ResponseEntity.status(status).body(detail);
120	    }
121	
122	    /**
123	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
124	     * method returns a 404 Not Found status if an entity does not exist.
125	     *
126	     * @param e The {@link DataIntegrityViolationException} to be handled
127	     * @param request {@link HttpServletRequest} object referring to the current request.
128	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
129	     */
130	    @ExceptionHandler(DataIntegrityViolationException.class)
131	    @ResponseBody
132	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
133	        logger.warn("Data integrity violation at {} {}: {}",
134	            request.getMethod(),
135	            request.getRequestURI(),
136	            e.getMessage());
137	        logger.debug("Data integrity violation stacktrace", e);
138	        HttpStatus status = HttpStatus.NOT_FOUND;
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
140	        return ResponseEntity.status(status).body(detail);
141	    }
142	
143	    /**
144	     * Handles exception thrown by Bean Validation on controller methods parameters
145	     *
146	     * @param e The {@link MethodArgumentNotValidException} to be handled
147	     * @param request {@link HttpServletRequest} object referring to the current request.
148	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
149	     */
150	    @ExceptionHandler(MethodArgumentNotValidException.class)
151	    @ResponseBody
152	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
153	        HttpStatus status = HttpStatus.BAD_REQUEST;
154	        BindingErrorsResponse errors = new BindingErrorsResponse();
155	        BindingResult bindingResult = e.getBindingResult();
156	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
157	        if (bindingResult.hasErrors()) {
158	            errors.addAllErrors(bindingResult);
159	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
160	                .map(fieldError -> {
161	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
162	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
163	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
164	                        fieldError.getField(),
165	                        defaultMessage,
166	                        rejectedValue);
167	                    return new ValidationMessageDto(message)
168	                        .putAdditionalProperty("field", fieldError.getField())
169	                        .putAdditionalProperty("rejectedValue", rejectedValue)
170	                        .putAdditionalProperty("defaultMessage", defaultMessage);
171	                })
172	                .toList();
173	            logger.debug("Validation error at {} {}: {}",
174	                request.getMethod(),
175	                request.getRequestURI(),
176	                bindingResult.getFieldErrors());
177	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
178	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
179	                .map(fieldError -> fieldError.getField())
180	                .distinct()
181	                .toList());
182	            return ResponseEntity.status(status).body(detail);
183	        }
184	        return ResponseEntity.status(status).body(detail);
185	    }
186	
187	}
