257	    private <T> T findEntityById(Supplier<T> supplier) {
258	        try {
259	            return supplier.get();
260	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
261	            // Just ignore not found exceptions for Jdbc/Jpa realization
262	            return null;
263	        }
264	    }
